using Microsoft.Testing.Platform.Builder;

namespace RoslynCodeLens.Tests;

/// <summary>
/// Manual replacement for xunit.v3's auto-generated entry point
/// (<c>XunitAutoGeneratedEntryPoint=false</c> in the .csproj).
/// </summary>
/// <remarks>
/// xunit's generated entry point routes normal console runs through
/// <c>Xunit.Runner.InProc.SystemConsole.ConsoleRunner</c>, which does NOT register
/// Microsoft.Testing.Platform extensions — it only wires them up on its
/// <c>--server</c> / <c>--internal-msbuild-node</c> branch. That makes MTP extension
/// options (notably CodeCoverage) unavailable for a direct <c>dotnet <exe></c> run.
/// Always routing through <see cref="Xunit.MicrosoftTestingPlatform.TestPlatformTestFramework"/>
/// registers the self-registered extensions (telemetry + code coverage) for every run,
/// so <c>--coverage</c> and friends work when tests are executed directly — the workflow
/// mandated by <c>.roo/rules-code/01-test.md</c> on the .NET 10 SDK, where the VSTest
/// target is no longer supported for MTP applications.
/// </remarks>
internal static class TestEntryPoint
{
    public static int Main(string[] args) =>
        Xunit.MicrosoftTestingPlatform.TestPlatformTestFramework
            .RunAsync(args, SelfRegisteredExtensions.AddSelfRegisteredExtensions)
            .GetAwaiter().GetResult();
}
